const CODE_VERSION = "find_booking_prepare_v1_contact_flexible";

const body = $json.body || $json;
const message = body.message || {};

const toolCall =
  message.toolCalls?.[0] ||
  message.toolCallList?.[0] ||
  message.toolWithToolCallList?.[0]?.toolCall ||
  null;

const toolCallId = toolCall?.id || $json.tool_call_id || null;
const toolName =
  toolCall?.function?.name ||
  $json.tool_name ||
  "find_booking";

let args = $json.args || toolCall?.function?.arguments || {};

if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch (error) {
    args = {};
  }
}

const customerName = String(args.customer_name || "").trim();
const city = String(args.city || "").trim();
const cityLower = city.toLowerCase();

const contactIdentifierRaw = String(
  args.contact_identifier ||
  args.phone_number ||
  args.phone ||
  args.email ||
  ""
).trim();

const currentAppointmentDateRaw = String(args.current_appointment_date || "").trim();
const currentAppointmentTimeRaw = String(args.current_appointment_time || "").trim();
const currentContext = String(args.current_datetime_context || "").trim();

function getTimeZoneName(cityText) {
  const city = String(cityText || "").toLowerCase();

  if (city.includes("doha")) return "Asia/Qatar";

  return "America/Chicago";
}

function getTimezoneOffset(cityText) {
  const city = String(cityText || "").toLowerCase();

  if (city.includes("doha")) return "+03:00";

  return "-05:00";
}

const timeZone = getTimeZoneName(city);
const timezoneOffset = getTimezoneOffset(city);

function pad(num) {
  return String(num).padStart(2, "0");
}

function offsetToMinutes(offset) {
  if (!offset || offset === "Z") return 0;

  const sign = offset.startsWith("-") ? -1 : 1;
  const [hours, minutes] = offset.slice(1).split(":").map(Number);

  return sign * (hours * 60 + minutes);
}

function fromTimestampToLocalParts(timestampMs, offset) {
  const localMs = timestampMs + offsetToMinutes(offset) * 60 * 1000;
  const localDate = new Date(localMs);

  return {
    year: localDate.getUTCFullYear(),
    month: localDate.getUTCMonth(),
    day: localDate.getUTCDate(),
    hour: localDate.getUTCHours(),
    minute: localDate.getUTCMinutes()
  };
}

function toIso(parts, offset) {
  return `${parts.year}-${pad(parts.month + 1)}-${pad(parts.day)}T${pad(parts.hour)}:${pad(parts.minute)}:00${offset}`;
}

function toUtcIso(localIsoWithOffset) {
  const date = new Date(localIsoWithOffset);

  if (isNaN(date.getTime())) {
    throw new Error("Invalid local ISO date: " + localIsoWithOffset);
  }

  return date.toISOString();
}

function addHours(parts, hours, offset) {
  const timestamp = new Date(toIso(parts, offset)).getTime();
  return fromTimestampToLocalParts(timestamp + hours * 60 * 60 * 1000, offset);
}

function addDays(parts, days, offset) {
  const timestamp = new Date(toIso(parts, offset)).getTime();
  return fromTimestampToLocalParts(timestamp + days * 24 * 60 * 60 * 1000, offset);
}

function parseCurrentContext(text, offset) {
  const value = String(text || "")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();

  if (!value) {
    return {
      parts: fromTimestampToLocalParts(Date.now(), offset),
      warning: "Missing current_datetime_context. Used server time as fallback."
    };
  }

  const isoMatch = value.match(
    /^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?$/
  );

  if (isoMatch) {
    return {
      parts: {
        year: Number(isoMatch[1]),
        month: Number(isoMatch[2]) - 1,
        day: Number(isoMatch[3]),
        hour: Number(isoMatch[4]),
        minute: Number(isoMatch[5])
      },
      warning: null
    };
  }

  const humanMatch = value.match(
    /(?:[A-Za-z]+,\s*)?([A-Za-z]+)\s+(\d{1,2}),\s+(\d{4}),\s+(\d{1,2}):(\d{2})\s*(AM|PM)/i
  );

  if (humanMatch) {
    const monthNames = {
      january: 0,
      february: 1,
      march: 2,
      april: 3,
      may: 4,
      june: 5,
      july: 6,
      august: 7,
      september: 8,
      october: 9,
      november: 10,
      december: 11
    };

    const month = monthNames[humanMatch[1].toLowerCase()];
    const day = Number(humanMatch[2]);
    const year = Number(humanMatch[3]);
    let hour = Number(humanMatch[4]);
    const minute = Number(humanMatch[5]);
    const ampm = humanMatch[6].toLowerCase();

    if (ampm === "pm" && hour < 12) hour += 12;
    if (ampm === "am" && hour === 12) hour = 0;

    return {
      parts: { year, month, day, hour, minute },
      warning: null
    };
  }

  return {
    parts: fromTimestampToLocalParts(Date.now(), offset),
    warning: `Could not parse current_datetime_context: ${value}. Used server time as fallback.`
  };
}

function getLocalDayOfWeek(parts) {
  return new Date(Date.UTC(parts.year, parts.month, parts.day)).getUTCDay();
}

function getNextWeekdayInfo(currentDayStart, targetWeekday, preferredDayText, offset) {
  const currentWeekday = getLocalDayOfWeek(currentDayStart);

  let daysToAdd = targetWeekday - currentWeekday;

  if (daysToAdd < 0) {
    daysToAdd += 7;
  }

  if (daysToAdd === 0 && preferredDayText.includes("next")) {
    daysToAdd = 7;
  }

  return addDays(currentDayStart, daysToAdd, offset);
}

function parseAppointmentDate(dateText, currentDayStart, offset) {
  const text = String(dateText || "").trim().toLowerCase();

  const monthNames = {
    january: 0,
    february: 1,
    march: 2,
    april: 3,
    may: 4,
    june: 5,
    july: 6,
    august: 7,
    september: 8,
    october: 9,
    november: 10,
    december: 11
  };

  const monthPattern = Object.keys(monthNames).join("|");

  const fullDateMatch = text.match(
    new RegExp(`(${monthPattern})\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,\\s*|\\s+)(\\d{4})`, "i")
  );

  if (fullDateMatch) {
    return {
      year: Number(fullDateMatch[3]),
      month: monthNames[fullDateMatch[1].toLowerCase()],
      day: Number(fullDateMatch[2]),
      hour: 0,
      minute: 0
    };
  }

  const isoDateMatch = text.match(/\d{4}-\d{2}-\d{2}/);

  if (isoDateMatch) {
    const [year, month, day] = isoDateMatch[0].split("-").map(Number);

    return {
      year,
      month: month - 1,
      day,
      hour: 0,
      minute: 0
    };
  }

  if (text.includes("today")) {
    return { ...currentDayStart };
  }

  if (text.includes("day after tomorrow")) {
    return addDays(currentDayStart, 2, offset);
  }

  if (text.includes("tomorrow")) {
    return addDays(currentDayStart, 1, offset);
  }

  const weekdays = {
    sunday: 0,
    monday: 1,
    tuesday: 2,
    wednesday: 3,
    thursday: 4,
    friday: 5,
    saturday: 6
  };

  for (const [weekdayName, weekdayNumber] of Object.entries(weekdays)) {
    if (text.includes(weekdayName)) {
      return getNextWeekdayInfo(currentDayStart, weekdayNumber, text, offset);
    }
  }

  return { ...currentDayStart };
}

function parseAppointmentTime(timeText) {
  const text = String(timeText || "").trim().toLowerCase();

  const match = text.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);

  if (!match) {
    throw new Error("Could not parse current_appointment_time: " + timeText);
  }

  let hour = Number(match[1]);
  const minute = match[2] ? Number(match[2]) : 0;
  const ampm = match[3]?.toLowerCase();

  if (!ampm && hour >= 1 && hour <= 7) {
    hour += 12;
  }

  if (ampm === "pm" && hour < 12) hour += 12;
  if (ampm === "am" && hour === 12) hour = 0;

  return { hour, minute };
}

function extractContactInfo(args, rawContact) {
  const combined = [
    rawContact,
    args.email,
    args.phone,
    args.phone_number
  ]
    .filter(Boolean)
    .join(" ")
    .trim();

  const emailMatch = combined.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  const email = emailMatch ? emailMatch[0].toLowerCase() : "";

  const withoutEmail = combined.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, " ");
  const phoneMatch = withoutEmail.match(/\+?\d[\d\s().-]{5,}\d/);
  const phoneNumber = phoneMatch ? phoneMatch[0].trim() : "";
  const phoneDigits = phoneNumber ? phoneNumber.replace(/\D/g, "") : "";

  let contactType = "unknown";
  if (email && phoneDigits) contactType = "both";
  else if (email) contactType = "email";
  else if (phoneDigits) contactType = "phone";

  return {
    contact_identifier_raw: combined,
    contact_type: contactType,
    email,
    phone_number: phoneNumber,
    phone_digits: phoneDigits
  };
}

const parsedCurrent = parseCurrentContext(currentContext, timezoneOffset);
const current = parsedCurrent.parts;

const currentDayStart = {
  year: current.year,
  month: current.month,
  day: current.day,
  hour: 0,
  minute: 0
};

const appointmentDate = parseAppointmentDate(
  currentAppointmentDateRaw,
  currentDayStart,
  timezoneOffset
);

const appointmentTime = parseAppointmentTime(currentAppointmentTimeRaw);

const appointmentStart = {
  year: appointmentDate.year,
  month: appointmentDate.month,
  day: appointmentDate.day,
  hour: appointmentTime.hour,
  minute: appointmentTime.minute
};

const appointmentEnd = addHours(appointmentStart, 1, timezoneOffset);

const searchDayStart = {
  year: appointmentDate.year,
  month: appointmentDate.month,
  day: appointmentDate.day,
  hour: 0,
  minute: 0
};

const searchDayEnd = addDays(searchDayStart, 1, timezoneOffset);

const appointmentStartLocal = toIso(appointmentStart, timezoneOffset);
const appointmentEndLocal = toIso(appointmentEnd, timezoneOffset);

const searchStartLocal = toIso(searchDayStart, timezoneOffset);
const searchEndLocal = toIso(searchDayEnd, timezoneOffset);

const contact = extractContactInfo(args, contactIdentifierRaw);

return [
  {
    json: {
      code_version: CODE_VERSION,

      tool_name: toolName,
      tool_call_id: toolCallId,

      customer_name: customerName,
      customer_name_normalized: customerName.toLowerCase(),

      city,
      city_lower: cityLower,
      timeZone,
      timezoneOffset,

      contact_identifier: contact.contact_identifier_raw,
      contact_type: contact.contact_type,
      email: contact.email,
      phone_number: contact.phone_number,
      phone_digits: contact.phone_digits,

      current_appointment_date_received: currentAppointmentDateRaw,
      current_appointment_time_received: currentAppointmentTimeRaw,

      current_datetime_context_received: currentContext,
      current_datetime_parse_warning: parsedCurrent.warning,
      current_local: toIso(current, timezoneOffset),

      appointment_start_local: appointmentStartLocal,
      appointment_end_local: appointmentEndLocal,
      appointment_start_utc: toUtcIso(appointmentStartLocal),
      appointment_end_utc: toUtcIso(appointmentEndLocal),

      search_start_local: searchStartLocal,
      search_end_local: searchEndLocal,
      search_start_utc: toUtcIso(searchStartLocal),
      search_end_utc: toUtcIso(searchEndLocal),

      appointment_time_label: `${currentAppointmentDateRaw} at ${currentAppointmentTimeRaw}`
    }
  }
];

const CODE_VERSION = "find_booking_match_v2";

const prep = $("Prepare Find Booking Data").first().json;

// Google Calendar may return multiple events as separate items
const events = $input
  .all()
  .map(item => item.json)
  .filter(event => event && event.id);

function normalizeText(value) {
  return String(value || "").toLowerCase().trim();
}

function normalizeDigits(value) {
  return String(value || "").replace(/\D/g, "");
}

function getEventText(event) {
  return [
    event.summary,
    event.description,
    event.location,
    event.attendees?.map(a => a.email).join(" ")
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function getEventStart(event) {
  return event.start?.dateTime || event.start?.date || "";
}

function getEventEnd(event) {
  return event.end?.dateTime || event.end?.date || "";
}

function getTimeDifferenceMinutes(eventStartIso, expectedStartIso) {
  const eventTime = new Date(eventStartIso).getTime();
  const expectedTime = new Date(expectedStartIso).getTime();

  if (isNaN(eventTime) || isNaN(expectedTime)) return null;

  return Math.abs(eventTime - expectedTime) / 60000;
}

function extractFromDescription(description, label) {
  const regex = new RegExp(`${label}:\\s*(.+)`, "i");
  const match = String(description || "").match(regex);

  if (!match) return "";

  return match[1].split("\n")[0].trim();
}

function extractEmail(event) {
  const text = getEventText(event);
  const match = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

  return match ? match[0].toLowerCase() : "";
}

function extractPhone(event) {
  const phone = extractFromDescription(event.description, "Phone");
  return phone || "";
}

function extractPhoneDigits(event) {
  return normalizeDigits(extractPhone(event));
}

const expectedStartUtc = prep.appointment_start_utc;
const customerName = normalizeText(prep.customer_name);
const customerNameParts = customerName.split(/\s+/).filter(Boolean);
const email = normalizeText(prep.email);
const phoneDigits = normalizeDigits(prep.phone_digits);
const city = normalizeText(prep.city);

const scoredMatches = events.map(event => {
  const eventText = getEventText(event);
  const eventStart = getEventStart(event);
  const eventEnd = getEventEnd(event);
  const eventPhoneDigits = extractPhoneDigits(event);

  const timeDiffMinutes = getTimeDifferenceMinutes(eventStart, expectedStartUtc);

  let score = 0;
  const reasons = [];

  if (timeDiffMinutes !== null && timeDiffMinutes <= 30) {
    score += 5;
    reasons.push("time_match");
  }

  const nameMatch =
    customerName &&
    (
      eventText.includes(customerName) ||
      customerNameParts.every(part => eventText.includes(part))
    );

  if (nameMatch) {
    score += 3;
    reasons.push("name_match");
  }

  if (email && eventText.includes(email)) {
    score += 5;
    reasons.push("email_match");
  }

  if (phoneDigits && eventPhoneDigits.includes(phoneDigits)) {
    score += 5;
    reasons.push("phone_match");
  }

  if (city && eventText.includes(city)) {
    score += 1;
    reasons.push("city_match");
  }

  return {
    event,
    score,
    reasons,
    eventStart,
    eventEnd,
    timeDiffMinutes
  };
})
.filter(item => item.score >= 7)
.sort((a, b) => b.score - a.score);

let result;

if (scoredMatches.length === 0) {
  result = {
    booking_found: false,
    multiple_possible_bookings: false,
    message: "No matching booking was found.",
    lookup: {
      customer_name: prep.customer_name,
      contact_type: prep.contact_type,
      email: prep.email || null,
      phone_number: prep.phone_number || null,
      city: prep.city,
      expected_appointment_start: prep.appointment_start_local,
      appointment_time_label: prep.appointment_time_label
    }
  };
} else if (scoredMatches.length > 1) {
  result = {
    booking_found: false,
    multiple_possible_bookings: true,
    message: "Multiple possible bookings were found. Please confirm the correct appointment.",
    possible_bookings: scoredMatches.slice(0, 3).map(item => ({
      calendar_event_id: item.event.id,
      appointment_start: item.eventStart,
      appointment_end: item.eventEnd,
      title: item.event.summary || "",
      city: prep.city
    }))
  };
} else {
  const matched = scoredMatches[0];
  const event = matched.event;

  const customerEmail =
    prep.email ||
    extractEmail(event) ||
    "";

  const customerPhone =
    prep.phone_number ||
    extractPhone(event) ||
    "";

  result = {
    booking_found: true,
    multiple_possible_bookings: false,
    message: "Booking found.",

    booking_id: event.id,
    calendar_event_id: event.id,

    customer_name: prep.customer_name,
    contact_type: prep.contact_type,
    email: customerEmail || null,
    phone_number: customerPhone || null,
    phone_digits: normalizeDigits(customerPhone) || prep.phone_digits || null,

    city: prep.city,
    pest_issue: extractFromDescription(event.description, "Pest Issue") || null,
    urgency: extractFromDescription(event.description, "Urgency") || null,
    service_address: extractFromDescription(event.description, "Service Address") || null,
    property_type: extractFromDescription(event.description, "Property Type") || null,
    notes: extractFromDescription(event.description, "Notes") || null,
    safety_notes: extractFromDescription(event.description, "Safety Notes") || null,

    old_appointment_start: matched.eventStart,
    old_appointment_end: matched.eventEnd,
    old_appointment_time_label: prep.appointment_time_label,

    match_score: matched.score,
    match_reasons: matched.reasons
  };
}

return [
  {
    json: {
      code_version: CODE_VERSION,
      results: [
        {
          toolCallId: prep.tool_call_id,
          result: JSON.stringify(result)
        }
      ]
    }
  }
];
